  "implementation": "def solve(case):
    payload = case['payload']
    wti = payload['word_token_indices']
    ws = payload['word_scores']
    fw = payload['forced_words']
    budget = payload['token_budget']
    forced_tokens = sum(len(wti[i]) for i in fw)
    if forced_tokens > budget:
        return {'words': [], 'tokens': []}
    remaining = []
    for i in range(len(wti)):
        if i not in set(fw):
            remaining.append((i, ws[i], len(wti[i])))
    remaining.sort(key=lambda x: (-x[1], x[0]))
    selected = list(fw)
    residual = budget - forced_tokens
    for idx, _, cost in remaining:
        if cost <= residual:
            selected.append(idx)
            residual -= cost
            if residual == 0:
                break
    if residual != 0:
        return {'words': [], 'tokens': []}
    sorted_selected = sorted(selected)
    tokens = []
    for idx in sorted_selected:
        tokens.extend(wti[idx])
    return {'words': sorted_selected, 'tokens': tokens}"
